<?php if (!empty($_SESSION['bulk_report'])): $bulkReport=$_SESSION['bulk_report']; ?>
<section class="card spaced" aria-label="Resultado de carga masiva"><h2>Resultado de la última carga masiva</h2><p class="muted"><?= (int)$bulkReport['file_count'] ?> PDF recibidos · <?= (int)$bulkReport['saved'] ?> historias guardadas · <?= (int)$bulkReport['reused'] ?> ya registradas · <?= (int)$bulkReport['failed'] ?> con errores<?= !empty($bulkReport['blocked']) ? ' · ' . (int)$bulkReport['blocked'] . ' grupos sin guardar' : '' ?>.</p>
<?php if (!empty($bulkReport['unreadable'])): ?><div class="notice warn"><?= ui_icon('alert') ?><p><strong><?= (int)$bulkReport['unreadable'] === 1 ? '1 PDF no se pudo leer y no se cargó.' : (int)$bulkReport['unreadable'] . ' PDF no se pudieron leer y no se cargaron.' ?></strong> Los demás se guardaron. Abajo está el motivo de cada uno. Si alguno era anexo de una atención que sí se guardó, esa historia quedó sin ese anexo: corrígelo y vuelve a subirlo junto con todos los PDF de esa atención.</p></div><?php endif ?>
<div class="table-wrap"><table class="responsive-table" role="table"><thead role="rowgroup"><tr role="row"><th scope="col" role="columnheader">Archivos</th><th scope="col" role="columnheader">Paciente / atención</th><th scope="col" role="columnheader">Resultado</th></tr></thead><tbody role="rowgroup">
<?php foreach($bulkReport['results'] as $result): ?><tr role="row"><td role="cell" data-label="Archivos" class="bulk-files"><?php foreach($result['previews'] ?? array_map(fn($file)=>['name'=>$file],$result['files']) as $preview): ?><div><?= ui_pdf_preview($preview, count($result['files']) === 1 && !empty($result['page']) ? (int)$result['page'] : null) ?></div><?php endforeach ?><?php if (!empty($result['page'])): ?><span class="pill stop bulk-page">Página <?= (int)$result['page'] ?></span><?php endif ?></td><td role="cell" data-label="Paciente / atención"><?= h($result['patient'] ?? 'No identificado') ?><small><?= h($result['document'] ?? '') ?></small><small><?= isset($result['date']) ? h(date('d/m/Y',strtotime($result['date']))) : '' ?></small></td><td role="cell" data-label="Resultado" class="bulk-result"><span class="pill <?= ['saved'=>'ok','reused'=>'info','error'=>'stop','blocked'=>'stop'][$result['status']] ?>"><?= h(['saved'=>'Guardada','reused'=>'Ya registrada','error'=>'No se cargó','blocked'=>'Sin guardar'][$result['status']]) ?></span><p><?= h($result['message']) ?></p><?php if (!empty($result['summary'])): $s = $result['summary']; $sent = array_column(array_filter($s['resolved'], fn($r) => $r['sent']), 'reference'); $held = array_column(array_filter($s['resolved'], fn($r) => !$r['sent']), 'reference'); ?><small><?= h($s['specialty']) ?> · Ingreso <?= h($s['admission']) ?> · <?= (int)$s['pages'] ?> <?= (int)$s['pages'] === 1 ? 'página' : 'páginas' ?></small><small><?= $s['orders'] ? 'Órdenes: ' . h(implode(', ', $s['orders'])) : 'Sin órdenes detectadas' ?></small><?php if ($sent): ?><small class="load-sent">Enviada a solicitud pendiente: <?= h(implode(', ', $sent)) ?></small><?php endif ?><?php if ($held): ?><small class="load-held">Revisar en Solicitudes: <?= h(implode(', ', $held)) ?></small><?php endif ?><?php endif ?></td></tr><?php endforeach ?>
</tbody></table></div></section><?php endif ?>
